class Internal(Exception): pass

def application_implicit():
    try:
        raise ValueError('original context')
    except ValueError:
        raise RuntimeError('application')

def application_explicit():
    try:
        raise ValueError('original cause')
    except ValueError as exc:
        raise RuntimeError('application') from exc

def application_suppressed():
    try:
        raise ValueError('hidden context')
    except ValueError:
        raise RuntimeError('application') from None

for factory in (application_implicit, application_explicit, application_suppressed):
    try:
        factory()
    except Exception as app_exc:
        original = (app_exc.__cause__, app_exc.__context__, app_exc.__suppress_context__)
    try:
        raise Internal('stream')
    except Internal:
        try:
            raise app_exc
        except Exception as reraised:
            inside = (reraised.__cause__, reraised.__context__, reraised.__suppress_context__)
    print(factory.__name__, 'original=', original, 'inside=', inside)

for factory in (application_implicit, application_explicit, application_suppressed):
    try:
        factory()
    except Exception as app_exc:
        pass
    try:
        raise Internal('stream')
    except Internal:
        should_raise = True
    if should_raise:
        try:
            raise app_exc
        except Exception as reraised:
            outside = (reraised.__cause__, reraised.__context__, reraised.__suppress_context__)
    print(factory.__name__, 'outside=', outside)
