import traceback
class Internal(Exception): pass

def make(mode):
    try:
        raise ValueError(mode)
    except ValueError as exc:
        if mode == 'implicit': raise RuntimeError('application')
        if mode == 'explicit': raise RuntimeError('application') from exc
        raise RuntimeError('application') from None

for mode in ('implicit', 'explicit', 'suppressed'):
    try:
        make(mode)
    except Exception as exc:
        app_exc = exc
    try:
        raise Internal('stream')
    except Internal:
        try:
            if app_exc.__suppress_context__ and app_exc.__cause__ is None:
                raise app_exc from None
            raise app_exc from (app_exc.__cause__ or app_exc.__context__)
        except Exception as out:
            print(mode, type(out.__cause__).__name__ if out.__cause__ else None, type(out.__context__).__name__ if out.__context__ else None, out.__suppress_context__)
            print(''.join(traceback.format_exception(out)))
PY"

